import math
import re
import unittest
import xml.etree.ElementTree as ET
from pathlib import Path

TARGET = Path(__file__).resolve().parent / "metro-map.svg"
REQUIRED_IDS = {"map", "backdrop", "river", "river-course", "bridges", "lines",
                "stations", "labels", "legend", "scale", "compass", "masthead"}
ON_LINE = 1.5           # a stop must sit this close to every route it serves
MIN_SEPARATION = 12.0   # two centrelines closer than this are touching
NEAR_INTERCHANGE = 30.0 # ... and touching is only allowed this close to one


def tag(el):
    return el.tag.split("}")[-1]


def num(value, default=None):
    try:
        return float(str(value).strip())
    except (TypeError, ValueError):
        return default


def classes(el):
    return set((el.get("class") or "").split())


def coords(raw):
    vals = [num(v) for v in re.split(r"[\s,]+", (raw or "").strip()) if v != ""]
    vals = [v for v in vals if v is not None]
    return [(vals[i], vals[i + 1]) for i in range(0, len(vals) - 1, 2)]


def seg_point_dist(p, a, b):
    (px, py), (ax, ay), (bx, by) = p, a, b
    dx, dy = bx - ax, by - ay
    den = dx * dx + dy * dy
    t = 0.0 if den == 0 else max(0.0, min(1.0, ((px - ax) * dx + (py - ay) * dy) / den))
    return math.hypot(px - (ax + t * dx), py - (ay + t * dy))


def poly_point_dist(p, pts):
    return min(seg_point_dist(p, pts[i], pts[i + 1]) for i in range(len(pts) - 1))


def seg_cross(a, b, c, d):
    def side(p, q, r):
        return (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])
    d1, d2 = side(c, d, a), side(c, d, b)
    d3, d4 = side(a, b, c), side(a, b, d)
    return ((d1 > 0) != (d2 > 0)) and ((d3 > 0) != (d4 > 0))


def polys_cross(p, q):
    for i in range(len(p) - 1):
        for j in range(len(q) - 1):
            if seg_cross(p[i], p[i + 1], q[j], q[j + 1]):
                return True
    return False


def walk(pts, step=2.0):
    out = []
    for i in range(len(pts) - 1):
        (ax, ay), (bx, by) = pts[i], pts[i + 1]
        length = math.hypot(bx - ax, by - ay)
        n = max(1, int(length / step))
        for k in range(n + 1):
            t = k / n
            out.append((ax + t * (bx - ax), ay + t * (by - ay)))
    return out


def arc_at(p, pts):
    """Distance along the polyline of the point on it nearest to p."""
    best, run, acc = (1e18, 0.0), 0.0, 0.0
    for i in range(len(pts) - 1):
        (ax, ay), (bx, by) = pts[i], pts[i + 1]
        dx, dy = bx - ax, by - ay
        den = dx * dx + dy * dy
        t = 0.0 if den == 0 else max(0.0, min(1.0, ((p[0] - ax) * dx + (p[1] - ay) * dy) / den))
        d = math.hypot(p[0] - (ax + t * dx), p[1] - (ay + t * dy))
        seg = math.hypot(dx, dy)
        if d < best[0]:
            best = (d, acc + t * seg)
        acc += seg
        run = acc
    return best[1], run


class Acceptance(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw = TARGET.read_text(encoding="utf-8")
        cls.root = ET.fromstring(cls.raw)
        cls.byid = {}
        for el in cls.root.iter():
            ident = el.get("id")
            if ident:
                cls.byid.setdefault(ident, el)
        cls.routes = {}
        for ident, el in cls.byid.items():
            m = re.fullmatch(r"route-([a-z])", ident or "")
            if not m:
                continue
            line = None
            for child in el.iter():
                if tag(child) == "polyline" and "centreline" in classes(child):
                    line = child
                    break
            cls.routes[m.group(1)] = {
                "group": el,
                "line": line,
                "pts": coords(line.get("points")) if line is not None else [],
                "stroke": (line.get("stroke") or "").strip().lower() if line is not None else "",
            }
        cls.stations = []
        for el in cls.root.iter():
            if "station" not in classes(el):
                continue
            cx, cy = num(el.get("cx")), num(el.get("cy"))
            if cx is None or cy is None:
                x1, y1 = num(el.get("x1")), num(el.get("y1"))
                x2, y2 = num(el.get("x2")), num(el.get("y2"))
                if None not in (x1, y1, x2, y2):
                    cx, cy = (x1 + x2) / 2.0, (y1 + y2) / 2.0
            cls.stations.append({
                "el": el, "xy": (cx, cy),
                "routes": (el.get("data-routes") or "").split(),
                "classes": classes(el),
            })

    def route_items(self):
        self.assertGreaterEqual(len(self.routes), 4, "fewer than 4 route-<letter> groups")
        return sorted(self.routes.items())

    # --- 1-4: the file itself -------------------------------------------
    def test_root_is_svg_with_viewbox(self):
        self.assertEqual(tag(self.root), "svg")
        box = (self.root.get("viewBox") or "").replace(",", " ").split()
        self.assertEqual(len(box), 4, "viewBox must have 4 numbers, got %r" % box)
        w, h = num(box[2]), num(box[3])
        self.assertTrue(w and w >= 600, "viewBox width too small: %r" % w)
        self.assertTrue(h and h >= 400, "viewBox height too small: %r" % h)

    def test_required_ids_present(self):
        missing = sorted(REQUIRED_IDS - set(self.byid))
        self.assertEqual(missing, [], "missing required ids: %s" % missing)

    def test_no_external_references(self):
        for el in self.root.iter():
            for key, value in el.attrib.items():
                if key.split("}")[-1] in ("href", "src") and re.match(r"\s*(https?:)?//", value or ""):
                    self.fail("external reference in %s: %s" % (tag(el), value))
        self.assertNotIn("@import", self.raw)
        self.assertFalse(re.search(r"url\(\s*['\"]?(https?:)?//", self.raw),
                         "external url() reference")

    def test_no_script_or_raster(self):
        kinds = {tag(el) for el in self.root.iter()}
        self.assertNotIn("script", kinds, "the map must not contain <script>")
        self.assertNotIn("image", kinds, "the map must be vector only, no <image>")
        self.assertNotIn("foreignObject", kinds)

    # --- 5-6: the routes -------------------------------------------------
    def test_four_routes_in_distinct_colours(self):
        seen = {}
        for key, route in self.route_items():
            self.assertIsNotNone(route["line"],
                                 'route-%s has no <polyline class="centreline">' % key)
            self.assertGreaterEqual(len(route["pts"]), 4,
                                    "route-%s needs at least 4 points, got %s"
                                    % (key, len(route["pts"])))
            colour = route["stroke"]
            self.assertTrue(colour, "route-%s centreline has no stroke colour" % key)
            self.assertNotIn(colour, seen,
                             "route-%s and route-%s share the colour %s"
                             % (key, seen.get(colour), colour))
            seen[colour] = key

    def test_every_segment_is_octolinear(self):
        for key, route in self.route_items():
            pts = route["pts"]
            for i in range(len(pts) - 1):
                (ax, ay), (bx, by) = pts[i], pts[i + 1]
                dx, dy = abs(bx - ax), abs(by - ay)
                self.assertGreater(max(dx, dy), 1.0,
                                   "route-%s has a zero-length segment at %s" % (key, pts[i]))
                ok = dx < 0.5 or dy < 0.5 or abs(dx - dy) <= 0.02 * max(dx, dy)
                self.assertTrue(ok, "route-%s segment %s->%s is neither 90 nor 45 degrees"
                                % (key, pts[i], pts[i + 1]))

    # --- 7: the river ----------------------------------------------------
    def test_at_least_two_routes_cross_the_river(self):
        course = self.byid.get("river-course")
        self.assertIsNotNone(course, "missing id=river-course")
        river = coords(course.get("points") or course.get("d"))
        self.assertGreaterEqual(len(river), 2, "river-course needs a point list")
        crossed = [k for k, r in self.route_items() if polys_cross(r["pts"], river)]
        self.assertGreaterEqual(len(crossed), 2,
                                "the network must cross the river: only %s does" % crossed)

    # --- 8-11: the stations ----------------------------------------------
    def test_interchanges_join_two_routes(self):
        marks = [s for s in self.stations if "interchange" in s["classes"]]
        self.assertGreaterEqual(len(marks), 3,
                                "a network this size needs 3+ interchanges, found %s" % len(marks))
        for s in marks:
            self.assertGreaterEqual(len(set(s["routes"])), 2,
                                    "interchange at %s serves %s" % (s["xy"], s["routes"]))

    def test_every_route_ends_at_a_terminus(self):
        for key, route in self.route_items():
            ends = [route["pts"][0], route["pts"][-1]]
            termini = [s for s in self.stations
                       if "terminus" in s["classes"] and key in s["routes"]]
            self.assertGreaterEqual(len(termini), 2,
                                    "route-%s has %s terminus markers" % (key, len(termini)))
            for end in ends:
                near = [s for s in termini if math.hypot(s["xy"][0] - end[0],
                                                         s["xy"][1] - end[1]) <= ON_LINE]
                self.assertTrue(near, "route-%s end %s has no terminus station" % (key, end))

    def test_every_station_sits_on_the_routes_it_serves(self):
        self.assertGreaterEqual(len(self.stations), 20,
                                "only %s stations on the whole network" % len(self.stations))
        for s in self.stations:
            self.assertIsNotNone(s["xy"][0], "a station has no usable position")
            self.assertTrue(s["routes"], "station at %s has no data-routes" % (s["xy"],))
            for key in s["routes"]:
                self.assertIn(key, self.routes,
                              "station at %s names unknown route %r" % (s["xy"], key))
                d = poly_point_dist(s["xy"], self.routes[key]["pts"])
                self.assertLessEqual(d, ON_LINE,
                                     "station at %s is %.2f off route-%s" % (s["xy"], d, key))

    def test_stops_are_evenly_spaced_along_each_route(self):
        for key, route in self.route_items():
            on = sorted(arc_at(s["xy"], route["pts"])[0]
                        for s in self.stations if key in s["routes"])
            self.assertGreaterEqual(len(on), 6, "route-%s has only %s stops" % (key, len(on)))
            gaps = [b - a for a, b in zip(on, on[1:])]
            self.assertTrue(all(g > 1.0 for g in gaps),
                            "route-%s has two stops in the same place" % key)
            self.assertLessEqual(max(gaps) / min(gaps), 2.5,
                                 "route-%s spacing is uneven: %.1f to %.1f"
                                 % (key, min(gaps), max(gaps)))

    # --- 12: no accidental overlaps --------------------------------------
    def test_routes_only_meet_at_marked_interchanges(self):
        marks = [s["xy"] for s in self.stations if "interchange" in s["classes"]]
        items = self.route_items()
        for i in range(len(items)):
            for j in range(i + 1, len(items)):
                ka, ra = items[i]
                kb, rb = items[j]
                for p in walk(ra["pts"]):
                    if poly_point_dist(p, rb["pts"]) >= MIN_SEPARATION:
                        continue
                    near = min((math.hypot(p[0] - m[0], p[1] - m[1]) for m in marks),
                               default=1e18)
                    self.assertLessEqual(
                        near, NEAR_INTERCHANGE,
                        "route-%s and route-%s touch at %s, %.0f from any interchange"
                        % (ka, kb, (round(p[0], 1), round(p[1], 1)), near))

    # --- 13-14: reading the map ------------------------------------------
    def test_legend_carries_every_route_colour(self):
        legend = self.byid.get("legend")
        self.assertIsNotNone(legend, "missing id=legend")
        paint = set()
        texts = 0
        for el in legend.iter():
            for key in ("stroke", "fill"):
                value = (el.get(key) or "").strip().lower()
                if value:
                    paint.add(value)
            if tag(el) == "text" and (el.text or "").strip():
                texts += 1
        self.assertGreaterEqual(texts, 4, "the legend needs a label per route, found %s" % texts)
        for key, route in self.route_items():
            self.assertIn(route["stroke"], paint,
                          "legend has no swatch in route-%s's colour %s" % (key, route["stroke"]))

    def test_scale_bar_and_compass(self):
        scale = self.byid.get("scale")
        compass = self.byid.get("compass")
        self.assertIsNotNone(scale, "missing id=scale")
        self.assertIsNotNone(compass, "missing id=compass")
        words = " ".join((el.text or "") for el in scale.iter() if tag(el) == "text")
        self.assertRegex(words, r"\d+\s*(km|m|mi)\b", "the scale bar needs a distance label")
        bars = [el for el in scale.iter() if tag(el) in ("line", "rect", "polyline", "path")]
        self.assertTrue(bars, "the scale needs a drawn bar")
        marks = " ".join((el.text or "") for el in compass.iter() if tag(el) == "text")
        self.assertRegex(marks.strip(), r"^N\b|\bN$", "the compass must be labelled N")
        arrow = [el for el in compass.iter()
                 if tag(el) in ("path", "polygon", "polyline", "line", "circle")]
        self.assertTrue(arrow, "the compass needs a drawn needle")


if __name__ == "__main__":
    unittest.main()
